export const newsModule = {
  abiVersion: 1, moduleId: 'community.hacker-news', version: '1.0.0',
  async collect({ sourceKey, params }, { signal }) {
    if (sourceKey !== 'topstories') throw new Error('Unknown source');
    const limit = params.limit ?? 20;
    if (!Number.isInteger(limit) || limit < 1 || limit > 50) throw new Error('Limit must be 1–50');
    const base = new URL(params.baseUrl ?? 'https://hacker-news.firebaseio.com/v0/');
    if (!['http:', 'https:'].includes(base.protocol) || base.username || base.password) throw new Error('Invalid API base');
    if (!base.pathname.endsWith('/')) base.pathname += '/';
    async function json(path) {
      const response = await fetch(new URL(path, base), { signal, redirect: 'error' });
      if (!response.ok) throw new Error('API request failed');
      return response.json();
    }
    const ids = await json('topstories.json');
    if (!Array.isArray(ids) || !ids.every(Number.isSafeInteger)) throw new Error('Invalid story IDs');
    const stories = await Promise.all(ids.slice(0, limit).map(id => json('item/' + id + '.json')));
    return stories.filter(s => s && !s.deleted && !s.dead).map(s => {
      if (!Number.isSafeInteger(s.id) || typeof s.title !== 'string' || !Number.isFinite(s.time)) throw new Error('Invalid story');
      return { externalId: String(s.id), title: s.title, content: s.text ?? '', url: s.url ?? 'https://news.ycombinator.com/item?id=' + s.id, publishedAt: new Date(s.time * 1000).toISOString() };
    });
  }
};
